package database

import (
	"context"
	"database/sql"

	"github.com/arandu-io/hesape/database/query"
)

// DB satisfies query.Connection, asserted here at compile time.
//
// It is what makes the handle a module constructor is given usable as a model
// connection directly, with no adapter in between and nothing to unwrap:
//
//	type WidgetRepository struct{ db *database.DB }
//
//	func (r *WidgetRepository) Open(ctx context.Context, g auth.Grant) ([]*Widget, error) {
//	    return model.Query[Widget](r.db).Where("status", "=", "open").Get(ctx, g)
//	}
//
// The alternative was a second type wrapping this one, and the reason it is not
// here is mechanical rather than aesthetic. A module that is handed one handle
// and queries through another has two routes to the same rows, and the second
// one is the route that has to be kept instrumented by hand: statements on it
// are recorded on the Collector only for as long as somebody remembers to
// forward them, and they join an open transaction only if the wrapper carries
// the same identity the transaction was opened on. The verbs below own no route
// to a database. Every one of them runs through QueryContext or ExecContext, so
// the recording, the placeholder numbering and the open transaction are the
// handle's, not theirs.
//
// One consequence is visible on the debug page. A statement issued here is
// recorded with the verb below as its origin rather than with the method that
// asked for it: the Collector reads the frame a fixed number of steps above
// itself, and a query built through the model layer arrives after the builder,
// the model and the verb, where a repository calling the handle arrives after
// one. The statement, its values and its duration are the same either way.
var _ query.Connection = (*DB)(nil)

// Select runs a select and returns its rows.
//
// The read-replica flag is accepted and ignored. A DB is one pool: there is no
// second one to send a select to instead, and a flag that silently selects the
// same pool is better than a signature that cannot be satisfied.
func (d *DB) Select(ctx context.Context, statement string, bindings []any, _ bool) ([]query.Record, error) {
	rows, err := d.QueryContext(ctx, statement, d.prepareBindings(bindings)...)
	if err != nil {
		return nil, err
	}
	defer func() { _ = rows.Close() }()

	return scanRecords(rows)
}

// Insert runs an insert, reporting whether it succeeded.
//
// # It does not report the identifier the engine assigned
//
// There is no GetLastInsertID here, and its absence is the decision rather than
// an omission. A DB is the pool, shared by every request the process is
// serving, so "the identifier of the last insert" on it is whoever inserted
// most recently -- which is the classic way one request is handed another
// request's row. Storing it here would make that a field.
//
// Nothing is lost by refusing. Identifiers in this framework are generated by
// the application, by NewID, into a text key -- an auto-incrementing column is
// not the shape a generated module has. Postgres, where one is used anyway,
// never asks: its processor compiles the insert with a returning clause and
// reads the identifier out of the result set, through Select. And a caller on
// an engine that does report one out of band gets a sentence naming exactly
// what is missing, from query/processors.ProcessInsertGetID, rather than a zero
// that reads like an identifier.
func (d *DB) Insert(ctx context.Context, statement string, bindings []any) (bool, error) {
	if _, err := d.exec(ctx, statement, bindings); err != nil {
		return false, err
	}
	return true, nil
}

// Update runs an update and returns the number of rows it changed.
func (d *DB) Update(ctx context.Context, statement string, bindings []any) (int64, error) {
	return d.affecting(ctx, statement, bindings)
}

// Delete runs a delete and returns the number of rows it removed.
func (d *DB) Delete(ctx context.Context, statement string, bindings []any) (int64, error) {
	return d.affecting(ctx, statement, bindings)
}

// Statement runs a statement that returns neither rows nor a count, reporting
// whether it succeeded.
func (d *DB) Statement(ctx context.Context, statement string, bindings []any) (bool, error) {
	if _, err := d.exec(ctx, statement, bindings); err != nil {
		return false, err
	}
	return true, nil
}

// GetQueryGrammar returns the grammar this handle's statements compile
// through: the one registered for its dialect.
func (d *DB) GetQueryGrammar() query.Grammar { return d.grammar }

// GetPostProcessor returns the processor this handle's results are read back
// through: the one registered for its dialect.
func (d *DB) GetPostProcessor() query.Processor { return d.processor }

// exec runs one statement through the instrumented handle.
func (d *DB) exec(ctx context.Context, statement string, bindings []any) (sql.Result, error) {
	return d.ExecContext(ctx, statement, d.prepareBindings(bindings)...)
}

// affecting runs a statement and reports how many rows it changed.
func (d *DB) affecting(ctx context.Context, statement string, bindings []any) (int64, error) {
	result, err := d.exec(ctx, statement, bindings)
	if err != nil || result == nil {
		return 0, err
	}

	count, err := result.RowsAffected()
	if err != nil {
		// A driver that cannot count is not a failed statement, so the count
		// is zero rather than an error.
		return 0, nil
	}
	return count, nil
}

// prepareBindings converts each binding into the value a driver accepts, using
// this handle's grammar.
func (d *DB) prepareBindings(bindings []any) []any {
	return prepareBindings(d.grammar, bindings)
}
